func clusterStatusDescription(view ClusterPageView) string {
	if view.LocalRole == "Primary" {
		return "This server accepts configuration changes and synchronizes replicas"
	}
	if view.LocalRole == "Replica" {
		return "This server answers DNS locally and synchronizes from the primary"
	}
	return "This server is operating independently"
}
func endpointLabel(value string) string {
	if value == "" {
		return "Not configured"
	}
	return value
}
func clusterFinalStepTitle(workflow string) string {
	if workflow == "join" {
		return "Join cluster"
	}
	return "Initialize primary"
}
func clusterWizardLastLabel(workflow string) string {
	if workflow == "join" {
		return "Join"
	}
	return "Cluster"
}
func clusterWizardStepClass(current, step int) string {
	if current > step {
		return "complete"
	}
	if current == step {
		return "current"
	}
	return ""
}
func clusterWizardNodeName(value, mode string) string {
	if mode == "" {
		return strings.SplitN(value, ".", 2)[0]
	}
	return value
}
func clusterWizardAdvertiseURL(value, mode string) string {
	if mode == "" && !strings.HasPrefix(value, "https://") {
		return ""
	}
	return value
}
func clusterWizardHTTPSHeading(workflow string) string {
	if workflow == "join" {
		return "Configure this replica's HTTPS"
	}
	return "Secure cluster communication"
}
func clusterWizardHTTPSDescription(workflow string) string {
	if workflow == "join" {
		return "Give this replica its own HTTPS endpoint before connecting it to the primary."
	}
	return "Every node must reach this server through trusted HTTPS."
}
func clusterWizardAdvertiseLabel(workflow string) string {
	if workflow == "join" {
		return "This Replica's HTTPS URL"
	}
	return "Primary HTTPS Console / API URL"
}
func clusterWizardAdvertisePlaceholder(workflow string) string {
	if workflow == "join" {
		return "https://localhost:5444"
	}
	return "https://dns-1.example.com:5443"
}
func clusterWizardAdvertiseHelp(workflow string) string {
	if workflow == "join" {
		return "The address recorded for this replica—not the primary URL. Enter the primary URL and enrollment token on the next step."
	}
	return "The public URL replicas use for enrollment, synchronization, and status."
}
func clusterWizardHTTPSListen(value, workflow string) string {
	if value != "" {
		return value
	}
	if workflow == "join" {
		return "127.0.0.1:5444"
	}
	return "127.0.0.1:5443"
}
func clusterWizardHTTPSListenHelp(workflow string) string {
	if workflow == "join" {
		return "When testing both nodes on one machine, use a different port from the primary (normally 5444 instead of 5443)."
	}
	return "The local address where Sable serves this HTTPS endpoint."
}
func firstNonEmptyPage(value, fallback string) string {
	if value != "" {
		return value
	}
	return fallback
}
func clusterNodeEndpoint(node ClusterNodeView) string {
	if node.AdvertiseURL != "" {
		return node.AdvertiseURL
	}
	if len(node.Addresses) > 0 {
		return node.Addresses[0]
	}
	return "No advertised endpoint"
}
func nodeStateBadge(state string) string {
	if state == "online" {
		return "status-badge active"
	}
	if state == "unreachable" {
		return "status-badge disabled"
	}
	return "status-badge"
}
func nodeStateLabel(state string) string {
	if state == "online" {
		return "Online"
	}
	if state == "unreachable" {
		return "Unreachable"
	}
	return "Unknown"
}
func nodeSyncBadge(state string) string { return "cluster-sync-badge " + state }
func syncStateLabel(state string) string {
	switch state {
	case "current":
		return "In sync"
	case "behind":
		return "Behind"
	case "unverified":
		return "Sync unverified"
	default:
		return "Sync unknown"
	}
}
func syncProgressMaximum(generation uint64) uint64 {
	if generation == 0 {
		return 1
	}
	return generation
}
func syncProgressLabel(node ClusterNodeView) string {
	if node.SyncState == "current" {
		return "Fully synchronized"
	}
	if node.SyncState == "unverified" {
		return "Awaiting primary verification"
	}
	if node.Lag > 0 {
		return fmt.Sprintf("%d generations behind", node.Lag)
	}
	return "Synchronization unavailable"
}
func nodeUptimeLabel(node ClusterNodeView) string {
	if node.UpSince == "" {
		return "Uptime unavailable"
	}
	if node.State == "unreachable" {
		return "Last reported up " + node.UpSince
	}
	return "Up " + node.UpSince
}
func nodeLagLabel(node ClusterNodeView) string {
	if node.SyncState == "unknown" || node.SyncState == "unverified" {
		return "Unknown"
	}
	return lagLabel(node.Lag)
}
func lagLabel(lag uint64) string {
	if lag == 0 {
		return "No lag"
	}
	if lag == 1 {
		return "1 generation"
	}
	return fmt.Sprintf("%d generations", lag)
}

